// Building footprints along a route from OpenStreetMap.
//
// 1. Alicante metropolitan area: static tiles published with the app
//    (public/buildings, generated by scripts/build-buildings.ts). Fast, and they do
//    not depend on the public Overpass servers, which are often saturated.
// 2. Routes that leave that area: live Overpass queries from the browser, split
//    into small stretches (at most two at a time) with a retry when a server is busy.
import { LatLng, simplifyPolyline, makeLocalProjection } from './geometry';
import { fetchWithTimeout, OSM_REQUEST_INIT } from './routing';

export interface BuildingFootprint {
  h: number; // height in meters
  p: LatLng[]; // outer ring, not closed
}

const OVERPASS_ENDPOINTS = [
  'https://overpass-api.de/api/interpreter',
  'https://maps.mail.ru/osm/tools/overpass/api/interpreter',
];
const REQUEST_TIMEOUT_MS = 35000;
const POINTS_PER_CHUNK = 25;
const MAX_PARALLEL = 2;

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

function estimateHeight(tags: Record<string, string> = {}): number {
  const h = parseFloat(tags.height || tags['building:height'] || '');
  if (Number.isFinite(h) && h > 0) return Math.min(200, Math.max(3, h));
  const levels = parseFloat(tags['building:levels'] || '');
  if (Number.isFinite(levels) && levels > 0) return Math.min(200, levels * 3.2 + 1);
  switch (tags.building) {
    case 'house':
    case 'detached':
    case 'semidetached_house':
    case 'terrace':
      return 7;
    case 'garage':
    case 'garages':
    case 'shed':
    case 'kiosk':
    case 'hut':
      return 3;
    case 'industrial':
    case 'warehouse':
    case 'retail':
      return 9;
    default:
      return 14; // typical 4-5 floor block in Alicante's Ensanche
  }
}

async function queryOverpass(query: string): Promise<any> {
  let lastError: unknown = null;
  for (const endpoint of OVERPASS_ENDPOINTS) {
    for (let attempt = 0; attempt < 2; attempt++) {
      try {
        // Form-encoded body and no custom headers: a "simple" CORS request, no preflight
        const res = await fetchWithTimeout(endpoint, REQUEST_TIMEOUT_MS, {
          ...OSM_REQUEST_INIT,
          method: 'POST',
          headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
          body: `data=${encodeURIComponent(query)}`,
        });
        if ((res.status === 429 || res.status === 504) && attempt === 0) {
          await sleep(2500);
          continue;
        }
        if (!res.ok) throw new Error(`${endpoint} respondió ${res.status}`);
        return await res.json();
      } catch (err) {
        lastError = err;
        break;
      }
    }
  }
  throw lastError instanceof Error ? lastError : new Error('Overpass no disponible');
}

// --- Static tiles ----------------------------------------------------------------
interface TileIndex {
  zoom: number;
  bbox: { minLat: number; maxLat: number; minLng: number; maxLng: number };
  tiles: string[];
}

let indexPromise: Promise<TileIndex | null> | null = null;
function loadTileIndex(): Promise<TileIndex | null> {
  if (!indexPromise) {
    indexPromise = fetchWithTimeout(`${import.meta.env.BASE_URL}buildings/index.json`, 15000)
      .then((r) => (r.ok ? r.json() : null))
      .catch(() => null);
  }
  return indexPromise;
}

const tileCache = new Map<string, Promise<BuildingFootprint[]>>();
function loadTile(zoom: number, key: string): Promise<BuildingFootprint[]> {
  let p = tileCache.get(key);
  if (!p) {
    p = fetchWithTimeout(`${import.meta.env.BASE_URL}buildings/${zoom}/${key}.json`, 20000)
      .then((r) => (r.ok ? r.json() : []))
      .then((records: number[][]) =>
        records.map((rec) => {
          // [height in dm, lat0, lng0, dlat1, dlng1, ...] in 1e-6 degrees
          let lat = rec[1];
          let lng = rec[2];
          const ring: LatLng[] = [[lat / 1e6, lng / 1e6]];
          for (let i = 3; i + 1 < rec.length; i += 2) {
            lat += rec[i];
            lng += rec[i + 1];
            ring.push([lat / 1e6, lng / 1e6]);
          }
          return { h: rec[0] / 10, p: ring };
        })
      );
    tileCache.set(key, p);
    p.catch(() => tileCache.delete(key));
  }
  return p;
}

const lng2tile = (lng: number, z: number) => Math.floor(((lng + 180) / 360) * 2 ** z);
const lat2tile = (lat: number, z: number) => {
  const r = (lat * Math.PI) / 180;
  return Math.floor(((1 - Math.log(Math.tan(r) + 1 / Math.cos(r)) / Math.PI) / 2) * 2 ** z);
};

async function streamFromTiles(
  index: TileIndex,
  coords: LatLng[],
  keepRadius: number,
  limit: number,
  onChunk: (b: BuildingFootprint[]) => void,
  isCancelled: () => boolean
): Promise<number> {
  const available = new Set(index.tiles);
  // Tiles touched by the route (and its corridor), in route order
  const line = simplifyPolyline(coords, 5);
  const order: string[] = [];
  const seenTiles = new Set<string>();
  const padLat = keepRadius / 111320;
  for (const [lat, lng] of line) {
    const padLng = keepRadius / (111320 * Math.cos((lat * Math.PI) / 180));
    for (const dLat of [-padLat, 0, padLat]) {
      for (const dLng of [-padLng, 0, padLng]) {
        const key = `${lng2tile(lng + dLng, index.zoom)}/${lat2tile(lat + dLat, index.zoom)}`;
        if (!seenTiles.has(key)) {
          seenTiles.add(key);
          if (available.has(key)) order.push(key);
        }
      }
    }
  }

  // Keep only buildings near the route (cheap test in local meters on the simplified line)
  const proj = makeLocalProjection(line[0][0], line[0][1]);
  const pts = simplifyPolyline(coords, 15).map(([lat, lng]) => proj.toXY(lat, lng));
  const nearRoute = (b: BuildingFootprint) => {
    const c = proj.toXY(b.p[0][0], b.p[0][1]);
    for (let i = 0; i < pts.length - 1; i++) {
      const a = pts[i];
      const d = pts[i + 1];
      const dx = d.x - a.x;
      const dy = d.y - a.y;
      const len2 = dx * dx + dy * dy || 1;
      const t = Math.max(0, Math.min(1, ((c.x - a.x) * dx + (c.y - a.y) * dy) / len2));
      if (Math.hypot(c.x - (a.x + t * dx), c.y - (a.y + t * dy)) <= keepRadius) return true;
    }
    return false;
  };

  let delivered = 0;
  for (let i = 0; i < order.length && !isCancelled() && delivered < limit; i += 3) {
    // three tiles at a time, in route order
    const batch = await Promise.all(order.slice(i, i + 3).map((key) => loadTile(index.zoom, key).catch(() => [])));
    const near = batch.flat().filter(nearRoute).slice(0, limit - delivered);
    delivered += near.length;
    if (near.length && !isCancelled()) onChunk(near);
  }
  return delivered;
}

// Uses the static tiles when the whole route is inside their area, live Overpass otherwise
export async function streamBuildings(
  coords: LatLng[],
  options: { overpassRadius: number; keepRadius: number; limit: number },
  onChunk: (buildings: BuildingFootprint[]) => void,
  isCancelled: () => boolean = () => false
): Promise<number> {
  const index = await loadTileIndex();
  if (index && coords.length > 0) {
    const { bbox } = index;
    const inside = coords.every(([lat, lng]) => lat >= bbox.minLat && lat <= bbox.maxLat && lng >= bbox.minLng && lng <= bbox.maxLng);
    if (inside) return streamFromTiles(index, coords, options.keepRadius, options.limit, onChunk, isCancelled);
  }
  return streamBuildingsAlongRoute(coords, options.overpassRadius, options.limit, onChunk, isCancelled);
}

// --- Live Overpass ----------------------------------------------------------------
// Results per stretch, so reopening a tour (or switching 3D mode) is instant
const chunkCache = new Map<string, any>();

// Streams the buildings stretch by stretch, starting at the beginning of the route,
// so the first ones appear in a few seconds instead of after the whole query.
// Resolves with the total number delivered; rejects only if every stretch failed.
export async function streamBuildingsAlongRoute(
  coords: LatLng[],
  radius: number,
  limit: number,
  onChunk: (buildings: BuildingFootprint[]) => void,
  isCancelled: () => boolean = () => false
): Promise<number> {
  // Overpass `around` accepts a polyline; keep it short
  let tolerance = 20;
  let line = simplifyPolyline(coords, tolerance);
  while (line.length > 150) {
    tolerance *= 1.6;
    line = simplifyPolyline(coords, tolerance);
  }
  const rounded = line.map(([lat, lng]) => [Math.round(lat * 1e6) / 1e6, Math.round(lng * 1e6) / 1e6] as LatLng);

  const chunks: LatLng[][] = [];
  for (let i = 0; i < rounded.length - 1; i += POINTS_PER_CHUNK - 1) chunks.push(rounded.slice(i, i + POINTS_PER_CHUNK));
  const perChunkLimit = Math.max(200, Math.ceil(limit / Math.max(1, chunks.length)) * 2);

  const seen = new Set<number>();
  let delivered = 0;
  let failures = 0;
  let lastError: unknown = null;
  let next = 0;

  const deliver = (data: any) => {
    const buildings: BuildingFootprint[] = [];
    for (const el of data?.elements || []) {
      if (delivered + buildings.length >= limit) break;
      if (el.type !== 'way' || !Array.isArray(el.geometry) || el.geometry.length < 4 || seen.has(el.id)) continue;
      seen.add(el.id);
      const ring: LatLng[] = el.geometry.map((g: { lat: number; lon: number }) => [g.lat, g.lon] as LatLng);
      const first = ring[0];
      const last = ring[ring.length - 1];
      if (first[0] === last[0] && first[1] === last[1]) ring.pop();
      if (ring.length >= 3) buildings.push({ h: estimateHeight(el.tags), p: ring });
    }
    delivered += buildings.length;
    if (buildings.length && !isCancelled()) onChunk(buildings);
  };

  const worker = async () => {
    while (next < chunks.length && !isCancelled() && delivered < limit) {
      const coordsStr = chunks[next++].map(([lat, lng]) => `${lat},${lng}`).join(',');
      const query =
        `[out:json][timeout:25];` +
        `way["building"]["building"!~"^(roof|construction|ruins|no)$"]["location"!="underground"](around:${radius},${coordsStr});` +
        `out geom qt ${perChunkLimit};`;
      try {
        let data = chunkCache.get(query);
        if (!data) {
          data = await queryOverpass(query);
          chunkCache.set(query, data);
        }
        deliver(data);
      } catch (err) {
        failures++;
        lastError = err;
      }
    }
  };
  await Promise.all(Array.from({ length: Math.min(MAX_PARALLEL, chunks.length) }, worker));
  if (failures > 0 && failures === chunks.length) {
    throw lastError instanceof Error ? lastError : new Error('Overpass no disponible');
  }
  return delivered;
}
